CATALOG = {
    "anthropic": {
        "deep_reasoning": "Claude Opus 4.5",
        "balanced": "Claude Sonnet 4.5",
        "fast": "Claude Haiku 4.5",
    },
    "openai": {
        "deep_reasoning": "o-series reasoning model",
        "balanced": "GPT flagship",
        "fast": "GPT mini",
    },
    "google": {
        "deep_reasoning": "Gemini 2.5 Pro",
        "balanced": "Gemini 2.5 Flash",
        "fast": "Gemini Flash-Lite",
    },
}

def pick_model(provider, need):
    tiers = CATALOG.get(provider)
    if tiers is None:
        return "unknown"
    return tiers.get(need, "unknown")

for provider, need in [
    ("anthropic", "deep_reasoning"),
    ("anthropic", "fast"),
    ("openai", "balanced"),
    ("google", "fast"),
]:
    print(f"{provider}/{need} -> {pick_model(provider, need)}")
print("providers=" + str(len(CATALOG)))
